    """Run the application."""
    return widget.describe(widget.build("demo"))

files.widget.py:
"""A small, healthy module."""


def build(name):
    """Build a widget with the given name."""
    return {"name": name}


def describe(widget):
    """Return a human-readable description of a widget."""
    return "widget: " + widget["name"]

files.tests/test_widget.py:
"""Tests for the widget module."""

import widget


def test_build():
    """build returns a dict with the name."""
    assert widget.build("a") == {"name": "a"}


def test_describe():
    """describe renders a widget."""
    assert widget.describe({"name": "a"}) == "widget: a"
